feat('HOP_REF_CREW_FOUL_RATE', 'Referee crew foul tendency', D, 'UNVERIFIED', 'unverified', 'Officials assigned to the game and their historical foul/FTA rates.', 'BoxScoreSummaryV3', 'BoxScoreSummaryV3.personId; BoxScoreSummaryV3.name; BoxScoreSummaryV3.familyName', 'Historical officials per game exist in V3 Officials (3 rows for the completed sample game). Assigned crews for an unplayed game were EMPTY when checked about 4.5 hours before tip (probed 15:28 EDT, tip 20:00 EDT); official assignments are normally published on game day by the league (external).', '', 'game', 'Verified for one completed 2025-26 game; depth UNTESTED.', 'Unverified (empty for unplayed game about 4.5h pre-tip)', 'ext', MISS['ext'], 'PTS:L,TOV:L', 'Only if assignments are obtained pregame.', 'P3', 'L/L/M/L/H', 'hop', 'hop', 'unverified_source')

# ---------------------------------------------------------------- VARIANCE
D = 'Game-level statistical variance'
_DISP = [('PTS', 'LBL_PTS', 'points', 'PTS:H,COMBO:M'), ('REB', 'LBL_REB', 'rebounds', 'REB:H,COMBO:M'), ('AST', 'LBL_AST', 'assists', 'AST:H,COMBO:M'),
         ('3PM', 'LBL_FG3M', 'three-pointers made', '3PM:H'), ('STL', 'LBL_STL', 'steals', 'STL:H'), ('BLK', 'LBL_BLK', 'blocks', 'BLK:H'),
         ('TOV', 'LBL_TOV', 'turnovers', 'TOV:H'), ('FGA', 'LBL_FGA', 'field-goal attempts (compound scoring pipeline)', 'PTS:H,COMBO:M'),
         ('FG3A', 'LBL_FG3A', 'three-point attempts (compound 3PM pipeline)', '3PM:H')]
for _m, _lbl, _nm, _rel in _DISP:
    feat(f'VAR_DISP_{_m}', f'Negative-binomial dispersion: {_nm}', D, 'ENGINEERED', 'lagged_observed',
         f'Overdispersion alpha of {_nm} (Var = mu + alpha*mu^2), fitted per market from historical TRAINING observations only. Market-specific on purpose: it never depends on another market forecast or on any final prediction output.', 'PlayerGameLogs',
         'PlayerGameLogs[Base].PTS; PlayerGameLogs[Base].REB; PlayerGameLogs[Base].AST; PlayerGameLogs[Base].FG3M; PlayerGameLogs[Base].FG3A; PlayerGameLogs[Base].FGA; PlayerGameLogs[Base].STL; PlayerGameLogs[Base].BLK; PlayerGameLogs[Base].TOV',
         f'alpha_{_m} = NB MLE of residuals y - mu_hat where mu_hat is the OUT-OF-FOLD forecast of the simple baseline MIN_ROLL x FRM_SHRUNK_RATE for this market (folds are chronological blocks inside the training window). Optionally pooled by archetype with shrinkage. Never fitted on validation/test dates and never on a model in-sample predictions.',
         f'{_lbl}; MIN_ROLL; FRM_SHRUNK_RATE', 'market (training window)', HIST['advgl'], PRE_LAG, 'proj|Parameter must be refit inside every walk-forward training window using out-of-fold residuals; a dispersion fit on the full history leaks future variance.', MISS['rookie'],
         _rel, 'Calibration (PIT histogram / interval coverage) of the market distribution on a later chronological block.', 'P0', 'H/M/L/M/M', 'variance', 'variance', 'hypothesis')

feat('VAR_ROLL_STD', 'Rolling standard deviation and CV', D, 'CALCULATED', 'lagged_observed', 'Sample std and coefficient of variation of each stat over the last N games.', 'PlayerGameLogs', 'PlayerGameLogs[Base].PTS; PlayerGameLogs[Base].REB; PlayerGameLogs[Base].AST; PlayerGameLogs[Base].FG3M', 'std_N = sqrt(sum((x_k-mean)^2)/(N-1)); cv = std/mean.', 'LBL_PTS; LBL_REB; LBL_AST; LBL_FG3M', 'player-game', HIST['advgl'], PRE_LAG, 'lag', MISS['roll'], ALLM.replace('H', 'M'), 'Compare against model-based dispersion; used mostly for over/under probability width.', 'P1', 'M/M/L/M/M', 'variance', 'variance', 'source_verified')
feat('VAR_QUANTILES_EMP', 'Empirical quantiles of recent outcomes', D, 'CALCULATED', 'lagged_observed', 'Empirical 10/25/50/75/90th percentiles of each stat over last 20 and 40 games.', 'PlayerGameLogs', 'PlayerGameLogs[Base].PTS; PlayerGameLogs[Base].REB; PlayerGameLogs[Base].AST', 'order statistics with linear interpolation.', '', 'player-game', HIST['advgl'], PRE_LAG, 'lag', MISS['roll'], ALLM.replace('H', 'M'), 'Baseline distribution for CRPS comparison.', 'P1', 'M/M/L/M/M', 'variance', 'variance', 'source_verified')
feat('VAR_ZERO_INFLATION', 'Zero-count probability', D, 'CALCULATED', 'lagged_observed', 'Share of recent games with 0 steals / 0 blocks / 0 threes: needed for correct tail probabilities in low-count markets.', 'PlayerGameLogs', 'PlayerGameLogs[Base].STL; PlayerGameLogs[Base].BLK; PlayerGameLogs[Base].FG3M', 'mean(x_k == 0) over last N games, shrunk to Poisson/NB-implied zero rate.', '', 'player-game', HIST['advgl'], PRE_LAG, 'lag', MISS['roll'], '3PM:M,STL:H,BLK:H', 'Check zero-inflation vs NB predictions.', 'P1', 'M/M/L/M/M', 'variance', 'variance', 'source_verified')
feat('VAR_STAT_CORR', 'Cross-stat correlation (combo markets)', D, 'ENGINEERED', 'lagged_observed', 'Within-game correlation between PTS, REB and AST (driven by shared minutes and pace) needed for correct combo-market distributions.', 'PlayerGameLogs', 'PlayerGameLogs[Base].PTS; PlayerGameLogs[Base].REB; PlayerGameLogs[Base].AST; PlayerGameLogs[Base].MIN', 'Residual correlation matrix of stats after conditioning on the OUT-OF-FOLD baseline means (MIN_ROLL x FRM_SHRUNK_RATE) and pace, fitted on training windows only - never on the final projected distributions; estimated per archetype with shrinkage. Joint simulation preserves it.', 'LBL_PTS; LBL_REB; LBL_AST; MIN_ROLL; FRM_SHRUNK_RATE; POS_TEAM_PACE_ROLL', 'player (as-of)', HIST['advgl'], PRE_LAG, 'lag', MISS['rookie'], 'COMBO:H', 'Compare combo calibration with independent vs correlated simulation.', 'P1', 'H/M/L/M/M', 'variance', 'variance', 'hypothesis')
feat('VAR_MIN_VOLATILITY', 'Minutes volatility', D, 'CALCULATED', 'lagged_observed', 'Std of minutes (excluding injury exits) over the last N games: widens all counting-stat distributions.', 'LeagueGameLog', 'LeagueGameLog.MIN', 'sample std of MIN over last 15 games, robust (MAD) variant also computed.', 'LBL_MIN', 'player-game', HIST['derived_box'], PRE_LAG, 'lag', MISS['roll'], ALLM.replace('H', 'M'), 'Does it improve minute-interval coverage?', 'P1', 'M/M/L/M/M', 'variance', 'variance', 'source_verified')
feat('VAR_STREAK_AUTOCORR', 'Hot/cold-streak autocorrelation', D, 'CALCULATED', 'lagged_observed', 'Lag-1 autocorrelation of shooting residuals: tests whether recent efficiency carries information beyond shrunk talent.', 'LeagueGameLog', 'LeagueGameLog.FGM; LeagueGameLog.FGA; LeagueGameLog.FG3M; LeagueGameLog.FG3A', 'corr(resid_t, resid_{t-1}) of (FG% - xFG or shrunk FG%) across player-games, pooled by season.', 'SHT_FG_PCT_SHRUNK', 'league-season', HIST['derived_box'], PRE_LAG, 'lag', MISS['none'], 'PTS:L,3PM:L', 'Diagnostic; if ~0 then shooting form features are noise.', 'P2', 'L/H/L/M/L', 'variance', 'variance', 'source_verified_untested_logic')

# ---------------------------------------------------------------- EXTERNAL
D = 'External data'
feat('EXT_INJURY_REPORT', 'Pregame injury report and game-day status', D, 'EXTERNAL', 'external_pregame', 'Official injury designations (Out / Doubtful / Questionable / Probable / Available) with timestamps. nba_api has no endpoint for them: none of the 142 library endpoints is an injury report (checked by name).', 'n/a', '', 'External feed; store every snapshot with timestamp; map status to probabilities empirically.', '', 'player-date-snapshot', HIST['ext'], PRE_EXT, 'ext', MISS['ext'], ALLM, 'Coverage and timeliness vs the chosen prediction cutoff.', 'P0', 'H/M/M/M/L', 'availability', 'availability', 'external_unobtained', 'Highest-value missing source.')
feat('EXT_CONFIRMED_STARTERS', 'Confirmed or expected starting lineups', D, 'EXTERNAL', 'external_pregame', 'Starting five (confirmed ~30 min before tip, expected earlier).', 'n/a', '', 'External feed with timestamps; historical starters are available from BoxScoreTraditionalV3 for training.', '', 'team-game', HIST['ext'], PRE_EXT, 'ext', MISS['ext'], 'PTS:H,REB:H,AST:H,3PM:H,TOV:H,COMBO:H', 'Does confirmation timing allow use at the chosen cutoff?', 'P1', 'H/M/M/M/L', 'starter', 'minutes_core', 'external_unobtained')
feat('EXT_PROP_LINES', 'Prop lines and odds (current and historical)', D, 'EXTERNAL', 'external_pregame', 'Sportsbook player-prop lines and prices by market. Needed to evaluate edge and as a (very strong) feature. NOT in nba_api: the Odds endpoint exposes only moneyline and spread.', 'n/a', '', 'External feed: book, market, line, over/under price, timestamp, open vs close.', '', 'player-game-market-snapshot', HIST['ext'], PRE_EXT, 'ext|Closing lines must never be used for a bet placed earlier. Using lines as a feature changes the problem to beating the market, not predicting the stat.', MISS['ext'], ALLM, 'Calibration vs lines; CLV analysis.', 'P0', 'H/H/H/H/L', 'market', 'market', 'external_unobtained', 'Required for any real backtest of betting value.')
feat('EXT_NEWS_TRANSACTIONS', 'News, trades, minute restrictions', D, 'EXTERNAL', 'external_pregame', 'Beat-reporter news: minute restrictions, rotation changes, return timelines, trades.', 'n/a', '', 'External text/feed; requires parsing and timestamping.', '', 'player-date', HIST['ext'], PRE_EXT, 'ext', MISS['ext'], 'PTS:M,REB:M,AST:M,COMBO:M', 'Only if structured.', 'P3', 'M/L/H/L/H', 'availability', 'availability', 'external_unobtained')

feat('EXP_REB_BASELINE', 'Expected rebounds (MVP baseline, rate-based)', 'Expected opportunities (projected)', 'ENGINEERED', 'projected',
     'MVP rebound projection that needs no tracking data: the player\'s rebound share while on court times the rebounds available during his projected minutes. Uses the verified REB% identity rearranged.', 'TeamGameLogs; PlayerGameLogs',
     'PlayerGameLogs[Advanced].REB_PCT; TeamGameLogs[Base].FGA; TeamGameLogs[Base].FGM; TeamGameLogs[Base].FTA; TeamGameLogs[Base].REB',
     'REB% = REB * TeamMIN / (MIN * (TmREB + OppREB))  (approximates the API REB_PCT; formula_checks.json reb_pct)  =>  E[REB] = REB%_hat * (E[MIN]/48) * TotalREB_exp, TotalREB_exp = a + b*misses_exp + c*FTA_exp with a,b,c re-fitted each season (2025-26 fit: 1.70, 0.873, 0.075; descriptive). The product of expectations ignores the covariance between minutes and the other terms - sample jointly. Distribution: NegBin(mean, alpha).',
     'MIN_EXP; REB_PCT_ROLL; ENV_EXP_MISSED_SHOTS; VAR_DISP_REB', G, HIST['advgl'], PRE_PROJ, 'proj', MISS['roll'], 'REB:H,COMBO:M',
     'Compare with the opportunity-based EXP_REB_DIST (rebound chances x conversion) in ablation: is tracking worth its cost?', 'P1', 'H/M/L/M/L', 'reb_pipeline', 'reb_opportunity', 'source_verified_untested_logic',
     'Baseline for the REB pipeline. Assumes REB% is stable at the projected minutes and that the rebound supply relation holds out of sample.')
feat('EXP_AST_BASELINE', 'Expected assists (MVP baseline, rate-based)', 'Expected opportunities (projected)', 'ENGINEERED', 'projected',
     'MVP assist projection that needs no tracking data: assist percentage times the teammate made field goals available during the player\'s projected minutes.', 'TeamGameLogs; PlayerGameLogs',
     'PlayerGameLogs[Advanced].AST_PCT; TeamGameLogs[Base].FGM; TeamGameLogs[Advanced].POSS; PlayerGameLogs[Base].FGM; PlayerGameLogs[Base].MIN',
     'AST% = AST / ((MIN/TeamMIN) * TmFGM - FGM)  (approximates the API AST_PCT; formula_checks.json ast_pct)  =>  E[AST] = AST%_hat * ( (E[MIN]/48) * TmFGM_exp - FGM_exp_i ); TmFGM_exp = poss_game * team FGM per possession (rolling, opponent-adjusted); FGM_exp_i = E[MIN] x shrunk FGM per minute (own rolling rate; deliberately NOT the points pipeline EXP_FGA, so this baseline stays independent of other markets). Distribution: NegBin(mean, alpha). Ignores who is on the floor with the player.',
     'MIN_EXP; AST_PCT_ROLL; ENV_EXP_GAME_POSS; FRM_SHRUNK_RATE; BOX_FGM; VAR_DISP_AST', G, HIST['advgl'], PRE_PROJ, 'proj', MISS['roll'], 'AST:H,COMBO:M',
     'Compare with the opportunity-based EXP_AST_DIST (potential assists x conversion) in ablation.', 'P1', 'H/M/L/M/L', 'assist_pipeline', 'assist_rate', 'source_verified_untested_logic',
     'Baseline for the AST pipeline.')

feat('EXP_COMBO_JOINT', 'Joint PTS/REB/AST simulation for combo markets', 'Expected opportunities (projected)', 'ENGINEERED', 'projected',
     'Combo-market (PRA, PR, PA, RA, STOCKS) distributions from a joint simulation that shares one minutes draw and one pace draw across stats, using the fitted dependence parameters.', 'PlayerGameLogs',
     'PlayerGameLogs[Base].PTS; PlayerGameLogs[Base].REB; PlayerGameLogs[Base].AST',
     'Draw minutes and pace once per simulated game; draw each stat from its marginal conditional on them; apply VAR_STAT_CORR dependence; sum for the combo. Marginals are the baseline or full pipeline outputs. Do not convolve independent marginals: that understates variance.',
     'EXP_PTS_DIST; EXP_REB_BASELINE; EXP_AST_BASELINE; VAR_STAT_CORR; ?EXP_REB_DIST; ?EXP_AST_DIST', 'player-game', HIST['advgl'], PRE_PROJ, 'proj', MISS['roll'], 'COMBO:H',
     'Calibration of P(combo > line) vs independent convolution.', 'P1', 'H/M/L/M/M', 'variance', 'variance', 'hypothesis')
